-- ===================== 0001_schema.sql =====================
-- Tosinfinity Academy — core schema, RLS and transactional workflows.
-- Idempotent: safe to re-run. One Owner; students; parents. No tutor/staff concepts.

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete restrict,
  role text not null check (role in ('owner','student','parent')),
  full_name text not null,
  email text not null,
  phone text,
  status text not null default 'active' check (status in ('active','inactive')),
  -- student-only fields
  student_code text unique,
  date_of_birth date,
  school_year text,
  curriculum text,
  location text,
  learning_needs text,
  goals text,
  delivery text check (delivery in ('home','online')),
  -- billing configuration (student rows; set by Owner only)
  billing_mode text check (billing_mode in ('hourly','flat_monthly','flat_term')),
  hourly_rate_minor bigint check (hourly_rate_minor >= 0),
  flat_fee_minor bigint check (flat_fee_minor >= 0),
  bill_absences boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists profiles_email_role_key on public.profiles (lower(email), role);
create unique index if not exists profiles_single_owner on public.profiles ((role)) where role = 'owner';
create index if not exists profiles_role_idx on public.profiles (role, status);

-- Owner-only private notes about a student (never visible to families).
create table if not exists public.student_notes (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  body text not null,
  created_at timestamptz not null default now()
);
create index if not exists student_notes_student_idx on public.student_notes (student_id, created_at desc);

create table if not exists public.applications (
  id uuid primary key default gen_random_uuid(),
  status text not null default 'new' check (status in ('new','in_review','approved','rejected')),
  student_name text not null,
  student_dob date,
  student_age int check (student_age between 3 and 99),
  student_email text,                   -- optional; the learner's own login email
  school_year text not null,
  curriculum text,
  location text,
  guardian_name text not null,
  guardian_email text not null,
  guardian_phone text not null,
  guardian_relationship text not null,
  subjects text[] not null default '{}',
  current_level text,
  exam_target text,
  delivery text not null check (delivery in ('home','online')),
  preferred_times text,
  challenges text,
  strengths text,
  desired_outcomes text,
  notes text,
  consent_at timestamptz not null,
  -- owner workflow
  internal_notes text,
  rejection_reason text,
  decided_at timestamptz,
  student_id uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists applications_status_idx on public.applications (status, created_at desc);

-- General enquiries from the public contact form.
create table if not exists public.contact_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  phone text,
  message text not null check (char_length(message) between 1 and 4000),
  handled_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.parent_student_links (
  id uuid primary key default gen_random_uuid(),
  parent_id uuid not null references public.profiles(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  relationship text not null default 'parent',
  verified_at timestamptz,          -- only verified links grant access
  created_at timestamptz not null default now(),
  unique (parent_id, student_id)
);
create index if not exists psl_student_idx on public.parent_student_links (student_id);

create table if not exists public.programmes (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  category text not null check (category in ('mathematics','science','exam_prep')),
  title text not null,
  summary text not null default '',
  description text not null default '',
  level text,
  sort_order int not null default 0,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.student_enrolments (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  programme_id uuid not null references public.programmes(id) on delete restrict,
  status text not null default 'active' check (status in ('active','paused','ended')),
  started_on date not null default current_date,
  ended_on date,
  created_at timestamptz not null default now()
);
create unique index if not exists enrolment_active_key
  on public.student_enrolments (student_id, programme_id) where status = 'active';

create table if not exists public.classes (
  id uuid primary key default gen_random_uuid(),
  series_id uuid,                       -- shared by sessions created as one recurring set
  title text not null,
  programme_id uuid references public.programmes(id) on delete set null,
  starts_at timestamptz not null,
  duration_minutes int not null check (duration_minutes between 10 and 600),
  delivery text not null check (delivery in ('home','online')),
  venue text,
  meeting_url text,
  objectives text,
  notes text,                           -- lesson notes shared with the family
  status text not null default 'scheduled' check (status in ('scheduled','completed','cancelled')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists classes_starts_idx on public.classes (starts_at);
-- Prevent accidental duplicate sessions (same title at the same instant).
create unique index if not exists classes_no_duplicate
  on public.classes (title, starts_at) where status <> 'cancelled';

create table if not exists public.class_students (
  class_id uuid not null references public.classes(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  primary key (class_id, student_id)
);
create index if not exists class_students_student_idx on public.class_students (student_id);

create table if not exists public.attendance (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  status text not null check (status in ('present','absent','late','excused')),
  actual_minutes int not null default 0 check (actual_minutes between 0 and 600),
  billable boolean not null default false,
  note text,
  recorded_at timestamptz not null default now(),
  unique (class_id, student_id)
);
create index if not exists attendance_student_idx on public.attendance (student_id);

create table if not exists public.assignments (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  instructions text not null default '',
  kind text not null check (kind in ('written','quiz','timed')),
  programme_id uuid references public.programmes(id) on delete set null,
  due_at timestamptz,
  max_marks numeric(7,2) not null default 100 check (max_marks > 0),
  time_limit_minutes int check (time_limit_minutes between 1 and 600),
  randomise boolean not null default false,
  allow_resubmission boolean not null default false,
  rubric jsonb not null default '[]'::jsonb,
  attachment_path text,
  published boolean not null default false,
