);

create table if not exists public.assignment_students (
  assignment_id uuid not null references public.assignments(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  primary key (assignment_id, student_id)
);
create index if not exists assignment_students_student_idx on public.assignment_students (student_id);

-- Holds correct answers: Owner-only. Students read questions through get_quiz_questions().
create table if not exists public.quiz_questions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments(id) on delete cascade,
  position int not null default 0,
  prompt text not null,
  options jsonb not null,               -- array of strings
  correct_index int not null check (correct_index >= 0),
  marks numeric(6,2) not null default 1 check (marks > 0)
);
create index if not exists quiz_questions_assignment_idx on public.quiz_questions (assignment_id, position);

create table if not exists public.submissions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  attempt int not null default 1 check (attempt >= 1),
  body text,
  file_path text,
  answers jsonb,
  started_at timestamptz,
  submitted_at timestamptz not null default now(),
  auto_score numeric(7,2),
  score numeric(7,2) check (score >= 0),
  feedback text,
  status text not null default 'submitted' check (status in ('submitted','graded')),
  graded_at timestamptz,
  unique (assignment_id, student_id, attempt)
);
create index if not exists submissions_student_idx on public.submissions (student_id, submitted_at desc);
create index if not exists submissions_status_idx on public.submissions (status);

