create table if not exists public.invoices (
  id uuid primary key default gen_random_uuid(),
  number text not null unique,
  student_id uuid not null references public.profiles(id) on delete restrict,
  kind text not null default 'tuition' check (kind in ('tuition','adhoc')),
  period_start date not null,
  period_end date not null,
  currency char(3) not null,
  status text not null default 'draft'
    check (status in ('draft','unpaid','partially_paid','paid','overdue','cancelled')),
  total_minor bigint not null default 0 check (total_minor >= 0),
  paid_minor bigint not null default 0,
  due_date date,
  issued_at timestamptz,
  notes text,
  created_at timestamptz not null default now(),
  check (period_end >= period_start)
);
-- Idempotency for scheduled generation: one tuition invoice per student per period.
create unique index if not exists invoices_period_key
  on public.invoices (student_id, period_start, period_end)
  where kind = 'tuition' and status <> 'cancelled';
create index if not exists invoices_student_idx on public.invoices (student_id, created_at desc);
create index if not exists invoices_status_idx on public.invoices (status, due_date);

