  method text not null check (method in ('paystack','bank_transfer','cash','adjustment')),
  reference text not null unique,       -- provider reference or owner-entered reference
  paid_at timestamptz not null default now(),
  recorded_by uuid references public.profiles(id) on delete set null,
  note text,
  provider_payload jsonb,
  created_at timestamptz not null default now()
);
create index if not exists payments_invoice_idx on public.payments (invoice_id);

-- Paystack checkout attempts; ties a provider reference to a legitimate invoice.
