-- ---------------------------------------------------------------------------
-- Helper functions (security definer so policies don't recurse into profiles RLS)
-- ---------------------------------------------------------------------------

create or replace function public.is_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles
                 where id = auth.uid() and role = 'owner' and status = 'active');
$$;

create or replace function public.is_parent_of(p_student uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.parent_student_links l
    join public.profiles p on p.id = l.parent_id and p.status = 'active'
    where l.parent_id = auth.uid() and l.student_id = p_student and l.verified_at is not null);
$$;

create or replace function public.can_view_student(p_student uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null
     and (public.is_owner() or auth.uid() = p_student or public.is_parent_of(p_student));
$$;

create or replace function public.current_role_name() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and status = 'active';
$$;

create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$ begin new.updated_at = now(); return new; end $$;

do $$ declare t text; begin
  foreach t in array array['profiles','programmes','classes','assignments','reports','blog_posts','settings'] loop
    execute format('drop trigger if exists touch_%1$s on public.%1$s', t);
    execute format('create trigger touch_%1$s before update on public.%1$s
                    for each row execute function public.touch_updated_at()', t);
  end loop;
end $$;

create or replace function public.write_audit(p_action text, p_entity text, p_entity_id text, p_meta jsonb default '{}'::jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_owner() or auth.role() = 'service_role') then
    raise exception 'not authorised';
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (auth.uid(), p_action, p_entity, p_entity_id, coalesce(p_meta, '{}'::jsonb));
end $$;

-- Student IDs such as TA-2026-001. Row lock makes concurrent calls safe.
create or replace function public.next_student_code() returns text
language plpgsql security definer set search_path = public as $$
declare y int := extract(year from now())::int; n int;
begin
  insert into public.student_code_counters (year, last_value) values (y, 1)
  on conflict (year) do update set last_value = public.student_code_counters.last_value + 1
  returning last_value into n;
  return format('TA-%s-%s', y, lpad(n::text, 3, '0'));
end $$;

create or replace function public.next_invoice_number() returns text
language plpgsql security definer set search_path = public as $$
declare y int := extract(year from now())::int; n int;
begin
  insert into public.invoice_counters (year, last_value) values (y, 1)
  on conflict (year) do update set last_value = public.invoice_counters.last_value + 1
  returning last_value into n;
  return format('INV-%s-%s', y, lpad(n::text, 4, '0'));
end $$;

-- Fixed-window rate limiter. Returns true when the call is allowed.
create or replace function public.check_rate_limit(p_key text, p_max int, p_window_seconds int)
returns boolean language plpgsql security definer set search_path = public as $$
declare w timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
        c int;
begin
  insert into public.rate_limits (key, window_start, count) values (p_key, w, 1)
  on conflict (key, window_start) do update set count = public.rate_limits.count + 1
  returning count into c;
  delete from public.rate_limits where window_start < now() - interval '1 day';
  return c <= p_max;
end $$;

-- ---------------------------------------------------------------------------
-- Application approval: one transaction, safe against double-approval.
-- The auth users are created first by the server (admin API); this function then
-- creates profiles, the verified parent link and marks the application approved.
-- ---------------------------------------------------------------------------
create or replace function public.approve_application(
  p_application uuid, p_student_user uuid, p_student_email text, p_parent_user uuid default null)
returns text language plpgsql security definer set search_path = public as $$
declare a public.applications%rowtype; v_code text;
begin
  if not (public.is_owner() or auth.role() = 'service_role') then
    raise exception 'not authorised';
  end if;
  select * into a from public.applications where id = p_application for update;
  if not found then raise exception 'application not found'; end if;
  if a.status = 'approved' then raise exception 'application already approved'; end if;
  if exists (select 1 from public.profiles where id = p_student_user) then
    raise exception 'student account already has a profile';
  end if;

  v_code := public.next_student_code();
  insert into public.profiles (id, role, full_name, email, student_code, date_of_birth,
                               school_year, curriculum, location, learning_needs, goals, delivery)
  values (p_student_user, 'student', a.student_name, p_student_email, v_code, a.student_dob,
          a.school_year, a.curriculum, a.location, a.challenges, a.desired_outcomes, a.delivery);

  if p_parent_user is not null then
    insert into public.profiles (id, role, full_name, email, phone)
    values (p_parent_user, 'parent', a.guardian_name, a.guardian_email, a.guardian_phone)
    on conflict (id) do nothing;
    if not exists (select 1 from public.profiles where id = p_parent_user and role = 'parent') then
      raise exception 'guardian email belongs to a non-parent account';
    end if;
    insert into public.parent_student_links (parent_id, student_id, relationship, verified_at)
    values (p_parent_user, p_student_user, a.guardian_relationship, now())
    on conflict (parent_id, student_id) do update set verified_at = now();
  end if;

  update public.applications
     set status = 'approved', decided_at = now(), student_id = p_student_user
   where id = p_application;

  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (auth.uid(), 'application.approved', 'application', p_application::text,
          jsonb_build_object('student_code', v_code));
  return v_code;
end $$;

-- ---------------------------------------------------------------------------
-- Payments ledger: append-only; invoice balance derived by trigger.
-- ---------------------------------------------------------------------------
create or replace function public.payments_immutable() returns trigger
language plpgsql as $$ begin raise exception 'payments are append-only'; end $$;
drop trigger if exists payments_no_update on public.payments;
create trigger payments_no_update before update or delete on public.payments
  for each row execute function public.payments_immutable();

create or replace function public.apply_payment() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_paid bigint; v_total bigint; v_status text;
begin
  select coalesce(sum(amount_minor), 0) into v_paid from public.payments where invoice_id = new.invoice_id;
  select total_minor, status into v_total, v_status from public.invoices where id = new.invoice_id for update;
  if v_status in ('draft','cancelled') then
    raise exception 'cannot record a payment against a % invoice', v_status;
  end if;
  update public.invoices
     set paid_minor = v_paid,
         status = case when v_paid >= v_total then 'paid'
                       when v_paid > 0 then 'partially_paid'
                       when due_date is not null and due_date < current_date then 'overdue'
                       else 'unpaid' end
   where id = new.invoice_id;
  return new;
end $$;
drop trigger if exists payments_apply on public.payments;
create trigger payments_apply after insert on public.payments
  for each row execute function public.apply_payment();

-- Credit a payment exactly once. Duplicate references (webhook retries) are a no-op.
-- Returns true when a new ledger row was written.
create or replace function public.credit_payment(
  p_invoice uuid, p_amount_minor bigint, p_currency text, p_method text, p_reference text,
  p_paid_at timestamptz default now(), p_note text default null, p_payload jsonb default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare inv public.invoices%rowtype; n int;
begin
  if not (public.is_owner() or auth.role() = 'service_role') then
    raise exception 'not authorised';
  end if;
  if p_method = 'paystack' and auth.role() <> 'service_role' then
    raise exception 'gateway payments are recorded by the server only';
  end if;
  select * into inv from public.invoices where id = p_invoice for update;
  if not found then raise exception 'invoice not found'; end if;
  if upper(p_currency) <> inv.currency then raise exception 'currency mismatch'; end if;

  insert into public.payments (invoice_id, amount_minor, currency, method, reference, paid_at,
                               recorded_by, note, provider_payload)
  values (p_invoice, p_amount_minor, upper(p_currency), p_method, p_reference, p_paid_at,
          auth.uid(), p_note, p_payload)
  on conflict (reference) do nothing;
  get diagnostics n = row_count;
  if n = 0 then return false; end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (auth.uid(), 'payment.recorded', 'invoice', p_invoice::text,
          jsonb_build_object('method', p_method, 'amount_minor', p_amount_minor, 'reference', p_reference));
  return true;
end $$;

-- ---------------------------------------------------------------------------
-- Quizzes: students never see correct answers; grading happens in the database.
-- ---------------------------------------------------------------------------
create or replace function public.student_has_assignment(p_assignment uuid, p_student uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.assignments a
                 join public.assignment_students s on s.assignment_id = a.id
                 where a.id = p_assignment and a.published and s.student_id = p_student);
$$;

create or replace function public.get_quiz_questions(p_assignment uuid)
returns table (id uuid, question_position int, prompt text, options jsonb, marks numeric)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_owner() or public.student_has_assignment(p_assignment, auth.uid())) then
    raise exception 'not authorised';
  end if;
  return query
    select q.id, q.position, q.prompt, q.options, q.marks
      from public.quiz_questions q where q.assignment_id = p_assignment order by q.position;
end $$;

-- p_answers: {"<question id>": <chosen option index>, ...}
create or replace function public.submit_quiz(p_assignment uuid, p_answers jsonb, p_started_at timestamptz default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare a public.assignments%rowtype; v_attempt int; v_raw numeric := 0; v_max numeric := 0;
        v_score numeric; v_id uuid; q record;
begin
  if not public.student_has_assignment(p_assignment, auth.uid()) then
    raise exception 'not authorised';
  end if;
  select * into a from public.assignments where id = p_assignment;
  if a.kind not in ('quiz','timed') then raise exception 'not a quiz'; end if;

  select coalesce(max(attempt), 0) + 1 into v_attempt
    from public.submissions where assignment_id = p_assignment and student_id = auth.uid();
  if v_attempt > 1 and not a.allow_resubmission then
    raise exception 'this quiz has already been submitted';
  end if;

  for q in select * from public.quiz_questions where assignment_id = p_assignment loop
    v_max := v_max + q.marks;
    if (p_answers ->> q.id::text) is not null
       and (p_answers ->> q.id::text) ~ '^[0-9]+$'
       and (p_answers ->> q.id::text)::int = q.correct_index then
      v_raw := v_raw + q.marks;
    end if;
  end loop;
  v_score := case when v_max > 0 then round(v_raw / v_max * a.max_marks, 2) else 0 end;

  insert into public.submissions (assignment_id, student_id, attempt, answers, started_at,
                                  auto_score, score, status, graded_at)
  values (p_assignment, auth.uid(), v_attempt, p_answers, p_started_at, v_score, v_score, 'graded', now())
  returning id into v_id;
  return v_id;
end $$;

-- Written work: attempt numbering and the resubmission rule are enforced here.
create or replace function public.submit_written(p_assignment uuid, p_body text, p_file_path text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare a public.assignments%rowtype; v_attempt int; v_id uuid;
begin
  if not public.student_has_assignment(p_assignment, auth.uid()) then
    raise exception 'not authorised';
  end if;
  select * into a from public.assignments where id = p_assignment;
  if a.kind <> 'written' then raise exception 'not a written assignment'; end if;
  if coalesce(trim(p_body), '') = '' and p_file_path is null then
    raise exception 'nothing to submit';
  end if;
  if p_file_path is not null
     and p_file_path not like auth.uid()::text || '/' || p_assignment::text || '/%' then
    raise exception 'invalid file path';
  end if;
  select coalesce(max(attempt), 0) + 1 into v_attempt
    from public.submissions where assignment_id = p_assignment and student_id = auth.uid();
  if v_attempt > 1 and not a.allow_resubmission then
    raise exception 'this assignment has already been submitted';
  end if;
  insert into public.submissions (assignment_id, student_id, attempt, body, file_path)
  values (p_assignment, auth.uid(), v_attempt, left(p_body, 20000), p_file_path)
  returning id into v_id;
  return v_id;
end $$;

-- Self-service profile edits are limited to harmless fields.
create or replace function public.update_own_profile(p_full_name text, p_phone text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  update public.profiles
     set full_name = left(trim(p_full_name), 120), phone = nullif(left(trim(p_phone), 30), '')
   where id = auth.uid();
end $$;

-- Mark messages in my thread as read (only those I did not send).
create or replace function public.mark_thread_read(p_thread uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_owner() or exists (select 1 from public.message_threads
                                       where id = p_thread and participant_id = auth.uid())) then
    raise exception 'not authorised';
  end if;
  update public.messages set read_at = now()
   where thread_id = p_thread and sender_id <> auth.uid() and read_at is null;
end $$;

create or replace function public.bump_thread() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.message_threads set last_message_at = new.created_at where id = new.thread_id;
  return new;
end $$;
drop trigger if exists messages_bump on public.messages;
create trigger messages_bump after insert on public.messages
  for each row execute function public.bump_thread();

-- Resolve a student ID to its login email. Service role only (called by the sign-in
-- server action, which then performs normal password authentication).
create or replace function public.email_for_student_code(p_code text) returns text
language sql stable security definer set search_path = public as $$
  select email from public.profiles
   where student_code = upper(trim(p_code)) and role = 'student' and status = 'active';
$$;

-- Lock function execution down, then grant precisely.
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on all functions in schema public to service_role;
grant execute on function public.is_owner(), public.is_parent_of(uuid), public.can_view_student(uuid),
  public.current_role_name(), public.student_has_assignment(uuid, uuid) to authenticated, anon;
grant execute on function public.write_audit(text, text, text, jsonb),
  public.approve_application(uuid, uuid, text, uuid),
  public.credit_payment(uuid, bigint, text, text, text, timestamptz, text, jsonb),
  public.get_quiz_questions(uuid), public.submit_quiz(uuid, jsonb, timestamptz),
  public.submit_written(uuid, text, text),
  public.update_own_profile(text, text), public.mark_thread_read(uuid),
  public.next_invoice_number() to authenticated;
-- email_for_student_code, check_rate_limit, next_student_code: service role only.

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
do $$ declare t text; begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- Drop & recreate so the migration is re-runnable.
do $$ declare r record; begin
  for r in select policyname, tablename from pg_policies where schemaname = 'public' loop
    execute format('drop policy if exists %I on public.%I', r.policyname, r.tablename);
  end loop;
end $$;

-- Owner: full access to academy-management tables.
do $$ declare t text; begin
  foreach t in array array[
    'profiles','student_notes','applications','contact_messages','parent_student_links','programmes','student_enrolments',
    'classes','class_students','attendance','assignments','assignment_students','quiz_questions',
    'submissions','materials','material_students','message_threads','messages','notices',
    'notice_recipients','notifications','invoices','invoice_items','reports','certificates',
    'blog_posts','blog_subscribers','settings','guardian_links'] loop
    execute format('create policy owner_all on public.%I for all to authenticated
                    using (public.is_owner()) with check (public.is_owner())', t);
  end loop;
end $$;

-- Ledger & audit: Owner may read; writes only through credit_payment()/write_audit().
create policy owner_read on public.payments for select to authenticated using (public.is_owner());
create policy owner_read on public.payment_intents for select to authenticated using (public.is_owner());
create policy owner_read on public.audit_log for select to authenticated using (public.is_owner());
-- rate_limits, job_runs, counters, push_subscriptions(write): no policies => service role only.

-- Profiles
create policy self_or_linked_read on public.profiles for select to authenticated
  using (id = auth.uid() or (role = 'student' and public.is_parent_of(id)));
-- Families need the Owner's name for messaging.
create policy owner_card_read on public.profiles for select to authenticated using (role = 'owner');

-- Public application form: insert only, never read.
create policy public_submit on public.applications for insert to anon, authenticated
  with check (status = 'new' and internal_notes is null and rejection_reason is null
              and decided_at is null and student_id is null);

create policy public_submit on public.contact_messages for insert to anon, authenticated
  with check (handled_at is null);

create policy own_links_read on public.parent_student_links for select to authenticated
  using (parent_id = auth.uid() or student_id = auth.uid());

create policy published_read on public.programmes for select to anon, authenticated using (is_published);

create policy family_read on public.student_enrolments for select to authenticated
  using (public.can_view_student(student_id));

create policy family_read on public.class_students for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.classes for select to authenticated
  using (exists (select 1 from public.class_students cs
                 where cs.class_id = id and public.can_view_student(cs.student_id)));

create policy family_read on public.attendance for select to authenticated
  using (public.can_view_student(student_id));

create policy family_read on public.assignment_students for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.assignments for select to authenticated
  using (published and exists (select 1 from public.assignment_students s
                               where s.assignment_id = id and public.can_view_student(s.student_id)));

create policy family_read on public.submissions for select to authenticated
  using (public.can_view_student(student_id));
-- Students submit only through submit_written()/submit_quiz(); marks are set by the Owner.

create policy family_read on public.material_students for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.materials for select to authenticated
  using (bucket = 'handouts'
         or exists (select 1 from public.material_students ms
                    where ms.material_id = id and public.can_view_student(ms.student_id))
         or exists (select 1 from public.student_enrolments e
                    where e.programme_id = materials.programme_id and e.status = 'active'
                      and public.can_view_student(e.student_id)));
create policy public_handouts on public.materials for select to anon using (bucket = 'handouts');

-- Messaging: one-to-one between the Owner and a single participant.
create policy participant_read on public.message_threads for select to authenticated
  using (participant_id = auth.uid());
create policy participant_create on public.message_threads for insert to authenticated
  with check (participant_id = auth.uid());
create policy participant_read on public.messages for select to authenticated
  using (exists (select 1 from public.message_threads t
                 where t.id = thread_id and t.participant_id = auth.uid()));
create policy participant_send on public.messages for insert to authenticated
  with check (sender_id = auth.uid() and read_at is null
              and exists (select 1 from public.message_threads t
                          where t.id = thread_id and t.participant_id = auth.uid()));

create policy audience_read on public.notices for select to authenticated
  using (published_at is not null and published_at <= now() and (
         audience = 'everyone'
      or (audience = 'all_students' and public.current_role_name() = 'student')
      or (audience = 'all_parents' and public.current_role_name() = 'parent')
      or exists (select 1 from public.notice_recipients r
                 where r.notice_id = id and r.profile_id = auth.uid())));
create policy own_read on public.notice_recipients for select to authenticated
  using (profile_id = auth.uid());

create policy own_read on public.notifications for select to authenticated using (user_id = auth.uid());
create policy own_mark_read on public.notifications for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

create policy family_read on public.invoices for select to authenticated
  using (status <> 'draft' and public.can_view_student(student_id));
create policy family_read on public.invoice_items for select to authenticated
  using (exists (select 1 from public.invoices i
                 where i.id = invoice_id and i.status <> 'draft' and public.can_view_student(i.student_id)));
create policy family_read on public.payments for select to authenticated
  using (exists (select 1 from public.invoices i
                 where i.id = invoice_id and public.can_view_student(i.student_id)));

create policy family_read on public.reports for select to authenticated
  using (status = 'published' and public.can_view_student(student_id));
create policy family_read on public.certificates for select to authenticated
  using (public.can_view_student(student_id));

create policy published_read on public.blog_posts for select to anon, authenticated
  using (status = 'published' and (publish_at is null or publish_at <= now()));

create policy public_read on public.settings for select to anon, authenticated using (is_public);

create policy own_read on public.push_subscriptions for select to authenticated using (user_id = auth.uid());

-- Column-level protection: notifications may only have read_at changed by their owner.
revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;

