-- ===================== 0002_storage.sql =====================
-- Storage buckets and access policies. Idempotent.
-- Path conventions (first folder decides ownership):
--   student-documents/<student_id>/...      submissions/<student_id>/<assignment_id>/...
--   reports/<student_id>/...                materials/<any>      message-attachments/<thread_id>/...

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('brand', 'brand', true, 2097152, array['image/png','image/jpeg','image/webp','image/svg+xml']),
  ('blog', 'blog', true, 5242880, array['image/png','image/jpeg','image/webp']),
  ('handouts', 'handouts', true, 20971520, array['application/pdf','image/png','image/jpeg','image/webp']),
  ('materials', 'materials', false, 52428800, array['application/pdf','image/png','image/jpeg','image/webp',
     'application/vnd.openxmlformats-officedocument.presentationml.presentation',
     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
     'application/vnd.ms-powerpoint','application/msword','text/plain']),
  ('student-documents', 'student-documents', false, 20971520, array['application/pdf','image/png','image/jpeg','image/webp']),
  ('submissions', 'submissions', false, 20971520, array['application/pdf','image/png','image/jpeg','image/webp',
     'application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain']),
  ('reports', 'reports', false, 10485760, array['application/pdf']),
  ('message-attachments', 'message-attachments', false, 10485760, array['application/pdf','image/png','image/jpeg','image/webp'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

do $$ declare r record; begin
  for r in select policyname from pg_policies
            where schemaname = 'storage' and tablename = 'objects' and policyname like 'ta_%' loop
    execute format('drop policy if exists %I on storage.objects', r.policyname);
  end loop;
end $$;

-- Owner manages every academy bucket.
create policy ta_owner_all on storage.objects for all to authenticated
  using (bucket_id in ('brand','blog','handouts','materials','student-documents','submissions','reports','message-attachments')
         and public.is_owner())
  with check (bucket_id in ('brand','blog','handouts','materials','student-documents','submissions','reports','message-attachments')
              and public.is_owner());

-- Public buckets are readable by anyone.
create policy ta_public_read on storage.objects for select to anon, authenticated
  using (bucket_id in ('brand','blog','handouts'));

-- Student-scoped private buckets: the student and verified parents may read.
create policy ta_family_read on storage.objects for select to authenticated
  using (bucket_id in ('student-documents','submissions','reports')
         and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'
         and public.can_view_student(((storage.foldername(name))[1])::uuid));

-- Students upload only into their own submissions folder, for an assignment they hold.
create policy ta_student_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'submissions'
              and (storage.foldername(name))[1] = auth.uid()::text
              and (storage.foldername(name))[2] ~ '^[0-9a-f-]{36}$'
              and public.student_has_assignment(((storage.foldername(name))[2])::uuid, auth.uid()));

-- Private materials: readable when the matching materials row is visible to the caller
-- (the materials table's own RLS applies inside this subquery).
create policy ta_material_read on storage.objects for select to authenticated
  using (bucket_id = 'materials'
         and exists (select 1 from public.materials m where m.bucket = 'materials' and m.path = name));

-- Message attachments: thread participant only (plus Owner via ta_owner_all).
create policy ta_attachment_read on storage.objects for select to authenticated
  using (bucket_id = 'message-attachments'
         and exists (select 1 from public.message_threads t
                     where t.id::text = (storage.foldername(name))[1] and t.participant_id = auth.uid()));
create policy ta_attachment_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'message-attachments'
              and exists (select 1 from public.message_threads t
                          where t.id::text = (storage.foldername(name))[1] and t.participant_id = auth.uid()));

-- ===================== 0003_notifications.sql =====================
-- In-app notifications raised by the database, so they cannot be forged or skipped
-- by a client. Idempotent.

create or replace function public.owner_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from public.profiles where role = 'owner' limit 1;
$$;

create or replace function public.area_for(p_user uuid) returns text
language sql stable security definer set search_path = public as $$
  select case role when 'owner' then '/owner' when 'student' then '/portal' else '/parent' end
    from public.profiles where id = p_user;
$$;

-- Notify a student and every verified parent.
create or replace function public.notify_family(p_student uuid, p_title text, p_body text, p_path text)
returns void language plpgsql security definer set search_path = public as $$
begin
  insert into public.notifications (user_id, title, body, href)
  select p_student, p_title, p_body, '/portal' || p_path
  union all
  select l.parent_id, p_title, p_body, '/parent' || p_path
    from public.parent_student_links l where l.student_id = p_student and l.verified_at is not null;
end $$;

-- New message → notify the other party. The body is never copied into the notification.
create or replace function public.on_message_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_participant uuid; v_owner uuid := public.owner_id();
begin
  select participant_id into v_participant from public.message_threads where id = new.thread_id;
  if new.sender_id = v_participant then
    if v_owner is not null then
      insert into public.notifications (user_id, title, body, href)
      values (v_owner, 'New message', (select full_name from public.profiles where id = new.sender_id),
              '/owner/messages/' || new.thread_id);
    end if;
  else
    insert into public.notifications (user_id, title, body, href)
    values (v_participant, 'New message', 'You have a new message from Tosinfinity Academy.',
            public.area_for(v_participant) || '/messages');
  end if;
  return new;
end $$;
drop trigger if exists messages_notify on public.messages;
create trigger messages_notify after insert on public.messages
  for each row execute function public.on_message_insert();

-- Submission received → Owner. Graded → family.
create or replace function public.on_submission_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_title text; v_owner uuid := public.owner_id();
begin
  select title into v_title from public.assignments where id = new.assignment_id;
  if tg_op = 'INSERT' and new.status = 'submitted' and v_owner is not null then
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'Work submitted', v_title, '/owner/assignments/' || new.assignment_id);
  elsif tg_op = 'UPDATE' and new.status = 'graded' and old.status is distinct from 'graded' then
    perform public.notify_family(new.student_id, 'Work marked', v_title, '/assignments');
  end if;
  return new;
end $$;
drop trigger if exists submissions_notify on public.submissions;
create trigger submissions_notify after insert or update on public.submissions
  for each row execute function public.on_submission_change();

-- Payment recorded → family and Owner.
create or replace function public.on_payment_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_student uuid; v_number text; v_owner uuid := public.owner_id();
begin
  select student_id, number into v_student, v_number from public.invoices where id = new.invoice_id;
  perform public.notify_family(v_student, 'Payment received', 'Invoice ' || v_number, '/invoices');
  if new.method = 'paystack' and v_owner is not null then
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'Online payment received', 'Invoice ' || v_number, '/owner/billing/' || new.invoice_id);
  end if;
  return new;
end $$;
drop trigger if exists payments_notify on public.payments;
create trigger payments_notify after insert on public.payments
  for each row execute function public.on_payment_insert();

-- New application or contact message → Owner.
create or replace function public.on_enquiry_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_owner uuid := public.owner_id();
begin
  if v_owner is null then return new; end if;
  if tg_table_name = 'applications' then
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'New application', new.student_name, '/owner/applications/' || new.id);
  else
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'New contact message', new.name, '/owner/applications?tab=messages');
  end if;
  return new;
end $$;
drop trigger if exists applications_notify on public.applications;
create trigger applications_notify after insert on public.applications
  for each row execute function public.on_enquiry_insert();
drop trigger if exists contact_notify on public.contact_messages;
create trigger contact_notify after insert on public.contact_messages
  for each row execute function public.on_enquiry_insert();

revoke execute on function public.owner_id(), public.area_for(uuid),
  public.notify_family(uuid, text, text, text) from public, anon, authenticated;
-- The Owner calls notify_family() from server actions (invoices, reports, classes).
create or replace function public.owner_notify_family(p_student uuid, p_title text, p_body text, p_path text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner() then raise exception 'not authorised'; end if;
  perform public.notify_family(p_student, left(p_title, 120), left(p_body, 300), p_path);
end $$;
revoke execute on function public.owner_notify_family(uuid, text, text, text) from public, anon;
grant execute on function public.owner_notify_family(uuid, text, text, text) to authenticated;

-- ===================== 0004_accounts.sql =====================
-- Account-creation helpers used by Owner workflows. Idempotent.

-- Find an existing login by email (service role only) so accounts are never duplicated.
create or replace function public.auth_user_id_by_email(p_email text) returns uuid
language sql stable security definer set search_path = public, auth as $$
  select id from auth.users where lower(email) = lower(trim(p_email)) limit 1;
$$;
revoke execute on function public.auth_user_id_by_email(text) from public, anon, authenticated;
grant execute on function public.auth_user_id_by_email(text) to service_role;

-- Create a student profile for an auth user (Owner adds a student directly, or CSV import).
create or replace function public.create_student_profile(p_user uuid, p_email text, p_fields jsonb)
returns text language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if not (public.is_owner() or auth.role() = 'service_role') then raise exception 'not authorised'; end if;
  if exists (select 1 from public.profiles where id = p_user) then
    raise exception 'this email already belongs to an account';
  end if;
  if coalesce(trim(p_fields ->> 'full_name'), '') = '' then raise exception 'full name is required'; end if;
  v_code := public.next_student_code();
  insert into public.profiles (id, role, full_name, email, phone, student_code, date_of_birth, school_year,
                               curriculum, location, learning_needs, goals, delivery)
  values (p_user, 'student', trim(p_fields ->> 'full_name'), lower(trim(p_email)),
          nullif(trim(p_fields ->> 'phone'), ''), v_code,
          nullif(p_fields ->> 'date_of_birth', '')::date, nullif(trim(p_fields ->> 'school_year'), ''),
          nullif(trim(p_fields ->> 'curriculum'), ''), nullif(trim(p_fields ->> 'location'), ''),
          nullif(trim(p_fields ->> 'learning_needs'), ''), nullif(trim(p_fields ->> 'goals'), ''),
          nullif(p_fields ->> 'delivery', ''));
  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (auth.uid(), 'student.created', 'profile', p_user::text, jsonb_build_object('student_code', v_code));
  return v_code;
end $$;

-- Create (or reuse) a parent profile and link it to a student as a verified relationship.
-- Only the Owner can do this, which is what makes the link "Owner-approved".
create or replace function public.link_parent(
  p_parent_user uuid, p_student uuid, p_full_name text, p_email text, p_phone text, p_relationship text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_owner() or auth.role() = 'service_role') then raise exception 'not authorised'; end if;
  if not exists (select 1 from public.profiles where id = p_student and role = 'student') then
    raise exception 'student not found';
  end if;
  insert into public.profiles (id, role, full_name, email, phone)
  values (p_parent_user, 'parent', trim(p_full_name), lower(trim(p_email)), nullif(trim(p_phone), ''))
  on conflict (id) do nothing;
  if not exists (select 1 from public.profiles where id = p_parent_user and role = 'parent') then
    raise exception 'that email belongs to a student or owner account and cannot be linked as a parent';
  end if;
  insert into public.parent_student_links (parent_id, student_id, relationship, verified_at)
  values (p_parent_user, p_student, coalesce(nullif(trim(p_relationship), ''), 'parent'), now())
  on conflict (parent_id, student_id) do update set verified_at = now(), relationship = excluded.relationship;
  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (auth.uid(), 'parent.linked', 'profile', p_student::text, jsonb_build_object('parent_id', p_parent_user));
end $$;

revoke execute on function public.create_student_profile(uuid, text, jsonb),
  public.link_parent(uuid, uuid, text, text, text, text) from public, anon;
grant execute on function public.create_student_profile(uuid, text, jsonb),
  public.link_parent(uuid, uuid, text, text, text, text) to authenticated, service_role;

-- ===================== 0005_quiz_timing.sql =====================
-- Server-side quiz timing. The start time is recorded in the database when the
-- student opens the questions, so it cannot be altered from the browser. Idempotent.

create table if not exists public.quiz_starts (
  assignment_id uuid not null references public.assignments(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  attempt int not null,
  started_at timestamptz not null default now(),
  primary key (assignment_id, student_id, attempt)
);
alter table public.quiz_starts enable row level security;
drop policy if exists owner_all on public.quiz_starts;
create policy owner_all on public.quiz_starts for all to authenticated
  using (public.is_owner()) with check (public.is_owner());
drop policy if exists own_read on public.quiz_starts;
create policy own_read on public.quiz_starts for select to authenticated using (student_id = auth.uid());

-- Records (once) when the current attempt began and returns that time.
create or replace function public.start_quiz(p_assignment uuid) returns timestamptz
language plpgsql security definer set search_path = public as $$
declare v_attempt int; v_started timestamptz; a public.assignments%rowtype;
begin
  if not public.student_has_assignment(p_assignment, auth.uid()) then raise exception 'not authorised'; end if;
  select * into a from public.assignments where id = p_assignment;
  if a.kind not in ('quiz','timed') then raise exception 'not a quiz'; end if;
  select coalesce(max(attempt), 0) + 1 into v_attempt
    from public.submissions where assignment_id = p_assignment and student_id = auth.uid();
  if v_attempt > 1 and not a.allow_resubmission then raise exception 'this quiz has already been submitted'; end if;
  insert into public.quiz_starts (assignment_id, student_id, attempt) values (p_assignment, auth.uid(), v_attempt)
  on conflict do nothing;
  select started_at into v_started from public.quiz_starts
   where assignment_id = p_assignment and student_id = auth.uid() and attempt = v_attempt;
  return v_started;
end $$;

-- submit_quiz now takes the start time from quiz_starts; p_started_at is ignored.
create or replace function public.submit_quiz(p_assignment uuid, p_answers jsonb, p_started_at timestamptz default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare a public.assignments%rowtype; v_attempt int; v_raw numeric := 0; v_max numeric := 0;
        v_score numeric; v_id uuid; q record; v_started timestamptz;
begin
  if not public.student_has_assignment(p_assignment, auth.uid()) then raise exception 'not authorised'; end if;
  select * into a from public.assignments where id = p_assignment;
  if a.kind not in ('quiz','timed') then raise exception 'not a quiz'; end if;
  if jsonb_typeof(p_answers) <> 'object' then raise exception 'invalid answers'; end if;

  select coalesce(max(attempt), 0) + 1 into v_attempt
    from public.submissions where assignment_id = p_assignment and student_id = auth.uid();
  if v_attempt > 1 and not a.allow_resubmission then raise exception 'this quiz has already been submitted'; end if;
  select started_at into v_started from public.quiz_starts
   where assignment_id = p_assignment and student_id = auth.uid() and attempt = v_attempt;

  for q in select * from public.quiz_questions where assignment_id = p_assignment loop
    v_max := v_max + q.marks;
    if (p_answers ->> q.id::text) ~ '^[0-9]{1,2}$' and (p_answers ->> q.id::text)::int = q.correct_index then
      v_raw := v_raw + q.marks;
    end if;
  end loop;
  v_score := case when v_max > 0 then round(v_raw / v_max * a.max_marks, 2) else 0 end;

  insert into public.submissions (assignment_id, student_id, attempt, answers, started_at,
                                  auto_score, score, status, graded_at)
  values (p_assignment, auth.uid(), v_attempt, p_answers, v_started, v_score, v_score, 'graded', now())
  returning id into v_id;
  return v_id;
end $$;

revoke execute on function public.start_quiz(uuid) from public, anon;
grant execute on function public.start_quiz(uuid) to authenticated;

-- ===================== 0006_billing_guards.sql =====================
-- Billing integrity rules enforced in the database. Idempotent.

-- Invoice numbers can only be drawn by the Owner or the server.
create or replace function public.next_invoice_number() returns text
language plpgsql security definer set search_path = public as $$
declare y int := extract(year from now())::int; n int;
begin
  if not (public.is_owner() or auth.role() = 'service_role') then raise exception 'not authorised'; end if;
  insert into public.invoice_counters (year, last_value) values (y, 1)
  on conflict (year) do update set last_value = public.invoice_counters.last_value + 1
  returning last_value into n;
  return format('INV-%s-%s', y, lpad(n::text, 4, '0'));
end $$;

-- Line items may only change while the invoice is a draft; the total always equals
-- the sum of the items, so it cannot drift from what the family is shown.
create or replace function public.invoice_items_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_invoice uuid := coalesce(new.invoice_id, old.invoice_id); v_status text;
begin
  select status into v_status from public.invoices where id = v_invoice for update;
  if v_status is null then
    return coalesce(new, old);   -- parent invoice is being deleted (cascade)
  end if;
  if v_status <> 'draft' then
    raise exception 'line items can only be changed while the invoice is a draft';
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists invoice_items_guard on public.invoice_items;
create trigger invoice_items_guard before insert or update or delete on public.invoice_items
  for each row execute function public.invoice_items_guard();

create or replace function public.invoice_items_total() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_invoice uuid := coalesce(new.invoice_id, old.invoice_id);
begin
  update public.invoices
     set total_minor = greatest(0, coalesce((select sum(amount_minor) from public.invoice_items where invoice_id = v_invoice), 0))
   where id = v_invoice;
  return null;
end $$;
drop trigger if exists invoice_items_total on public.invoice_items;
create trigger invoice_items_total after insert or update or delete on public.invoice_items
  for each row execute function public.invoice_items_total();

-- Once issued, an invoice's money fields are frozen. Status may move only along the
-- permitted paths; paid_minor is written solely by the payments trigger.
create or replace function public.invoices_guard() returns trigger
language plpgsql as $$
begin
  if old.status <> 'draft' then
    if new.student_id <> old.student_id or new.currency <> old.currency
       or new.period_start <> old.period_start or new.period_end <> old.period_end
       or new.number <> old.number then
      raise exception 'an issued invoice cannot be altered; cancel it and create a new one';
    end if;
    if new.total_minor <> old.total_minor then
      raise exception 'the total of an issued invoice cannot change';
    end if;
  end if;
  if new.status = 'cancelled' and old.status <> 'cancelled' and old.paid_minor <> 0 then
    raise exception 'an invoice with payments cannot be cancelled';
  end if;
  if old.status = 'cancelled' and new.status <> 'cancelled' then
    raise exception 'a cancelled invoice cannot be reopened';
  end if;
  if new.status = 'draft' and old.status <> 'draft' then
    raise exception 'an issued invoice cannot return to draft';
  end if;
  return new;
end $$;
drop trigger if exists invoices_guard on public.invoices;
create trigger invoices_guard before update on public.invoices
  for each row execute function public.invoices_guard();

-- Financial records are retained: an invoice can be deleted only while it is a draft.
create or replace function public.invoices_no_delete() returns trigger
language plpgsql as $$
begin
  if old.status <> 'draft' then
    raise exception 'issued invoices are kept for audit; cancel instead of deleting';
  end if;
  return old;
end $$;
drop trigger if exists invoices_no_delete on public.invoices;
create trigger invoices_no_delete before delete on public.invoices
  for each row execute function public.invoices_no_delete();

-- A person with financial history cannot be hard-deleted (profiles → invoices is RESTRICT).
-- Deactivate the account instead; this keeps the audit trail intact.

insert into public.settings (key, value, is_public) values
  ('billing', jsonb_build_object('invoice_day', 1, 'due_days', 7, 'reminder_days_before', 3, 'auto_issue', false), false)
on conflict (key) do nothing;

-- ===================== 0007_push_and_audit.sql =====================
-- Web Push subscriptions (own rows only) and an immutable audit log. Idempotent.

drop policy if exists own_insert on public.push_subscriptions;
create policy own_insert on public.push_subscriptions for insert to authenticated
  with check (user_id = auth.uid());
drop policy if exists own_delete on public.push_subscriptions;
create policy own_delete on public.push_subscriptions for delete to authenticated
  using (user_id = auth.uid());

-- The audit log is append-only for everyone, including the service role.
create or replace function public.audit_immutable() returns trigger
language plpgsql as $$ begin raise exception 'the audit log cannot be changed'; end $$;
drop trigger if exists audit_no_change on public.audit_log;
create trigger audit_no_change before update or delete on public.audit_log
  for each row execute function public.audit_immutable();

-- ===================== 0008_class_engagement.sql =====================
-- Lesson room: attendance confirmation, questions, quick checks (polls), understanding
-- check-ins, lesson recap and per-class materials. Works for home and online classes.
-- Idempotent.

alter table public.classes add column if not exists recap text;
alter table public.classes add column if not exists homework text;
alter table public.classes add column if not exists recording_url text;
alter table public.classes add column if not exists recap_at timestamptz;
alter table public.classes add column if not exists tutor_en_route_at timestamptz;

-- "I'll be there" / "I can't make it", given by the student or a verified parent.
create table if not exists public.class_rsvps (
  class_id uuid not null references public.classes(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  response text not null check (response in ('attending','not_attending')),
  note text check (char_length(note) <= 300),
  responded_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (class_id, student_id)
);

-- A learner's question about a lesson. Private between that learner (and their
-- parents) and the tutor, even in a shared class.
create table if not exists public.class_questions (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  body text not null check (char_length(body) between 3 and 1000),
  answer text check (char_length(answer) <= 3000),
  answered_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists class_questions_class_idx on public.class_questions (class_id, created_at);

-- Quick checks the tutor opens during a lesson. correct_index is optional and is
-- never sent to learners while the check is open.
create table if not exists public.class_polls (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes(id) on delete cascade,
  question text not null check (char_length(question) between 3 and 500),
  options jsonb not null,
  correct_index int check (correct_index >= 0),
  status text not null default 'open' check (status in ('open','closed')),
  created_at timestamptz not null default now(),
  closed_at timestamptz
);
create index if not exists class_polls_class_idx on public.class_polls (class_id, created_at);

create table if not exists public.class_poll_answers (
  poll_id uuid not null references public.class_polls(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  choice int not null check (choice >= 0),
  created_at timestamptz not null default now(),
  primary key (poll_id, student_id)
);

-- After the lesson: how well the learner feels they understood (1 = lost … 4 = confident).
create table if not exists public.class_feedback (
  class_id uuid not null references public.classes(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  understanding smallint not null check (understanding between 1 and 4),
  comment text check (char_length(comment) <= 1000),
  created_at timestamptz not null default now(),
  primary key (class_id, student_id)
);

-- Materials attached to one lesson; visible to the learners in that class.
create table if not exists public.class_materials (
  class_id uuid not null references public.classes(id) on delete cascade,
  material_id uuid not null references public.materials(id) on delete cascade,
  primary key (class_id, material_id)
);

alter table public.class_rsvps enable row level security;
alter table public.class_questions enable row level security;
alter table public.class_polls enable row level security;
alter table public.class_poll_answers enable row level security;
alter table public.class_feedback enable row level security;
alter table public.class_materials enable row level security;

create or replace function public.student_in_class(p_class uuid, p_student uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.class_students where class_id = p_class and student_id = p_student);
$$;

-- ---------------------------------------------------------------------------
-- Policies. Learners never write these tables directly; they go through the
-- functions below, which check class membership and timing.
-- ---------------------------------------------------------------------------
do $$ declare t text; begin
  foreach t in array array['class_rsvps','class_questions','class_polls','class_poll_answers','class_feedback','class_materials'] loop
    execute format('drop policy if exists owner_all on public.%I', t);
    execute format('create policy owner_all on public.%I for all to authenticated
                    using (public.is_owner()) with check (public.is_owner())', t);
    execute format('drop policy if exists family_read on public.%I', t);
  end loop;
end $$;

create policy family_read on public.class_rsvps for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.class_questions for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.class_feedback for select to authenticated
  using (public.can_view_student(student_id));
create policy family_read on public.class_poll_answers for select to authenticated
  using (student_id = auth.uid());
create policy family_read on public.class_materials for select to authenticated
  using (exists (select 1 from public.class_students cs
                 where cs.class_id = class_materials.class_id and public.can_view_student(cs.student_id)));
-- class_polls: Owner only. Learners read polls through get_class_polls().

-- Materials become visible when attached to a class the learner is in.
drop policy if exists family_read on public.materials;
create policy family_read on public.materials for select to authenticated
  using (bucket = 'handouts'
         or exists (select 1 from public.material_students ms
                    where ms.material_id = id and public.can_view_student(ms.student_id))
         or exists (select 1 from public.student_enrolments e
                    where e.programme_id = materials.programme_id and e.status = 'active'
                      and public.can_view_student(e.student_id))
         or exists (select 1 from public.class_materials cm
                    join public.class_students cs on cs.class_id = cm.class_id
                    where cm.material_id = materials.id and public.can_view_student(cs.student_id)));

-- ---------------------------------------------------------------------------
-- Learner actions
-- ---------------------------------------------------------------------------
create or replace function public.set_class_rsvp(p_class uuid, p_student uuid, p_response text, p_note text default null)
returns void language plpgsql security definer set search_path = public as $$
declare c public.classes%rowtype; v_owner uuid := public.owner_id();
begin
  if auth.uid() is null or not (auth.uid() = p_student or public.is_parent_of(p_student)) then
    raise exception 'not authorised';
  end if;
  if not public.student_in_class(p_class, p_student) then raise exception 'not authorised'; end if;
  if p_response not in ('attending','not_attending') then raise exception 'invalid response'; end if;
  select * into c from public.classes where id = p_class;
  if c.status <> 'scheduled' or c.starts_at < now() then
    raise exception 'this class has already started or is no longer scheduled';
  end if;
  insert into public.class_rsvps (class_id, student_id, response, note, responded_by, updated_at)
  values (p_class, p_student, p_response, nullif(left(trim(coalesce(p_note, '')), 300), ''), auth.uid(), now())
  on conflict (class_id, student_id) do update
    set response = excluded.response, note = excluded.note, responded_by = excluded.responded_by, updated_at = now();
  if p_response = 'not_attending' and v_owner is not null then
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'A learner cannot attend', c.title, '/owner/classes/' || p_class || '/room');
  end if;
end $$;

create or replace function public.ask_class_question(p_class uuid, p_body text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_owner uuid := public.owner_id(); v_title text;
begin
  if auth.uid() is null or not public.student_in_class(p_class, auth.uid()) then raise exception 'not authorised'; end if;
  if (select count(*) from public.class_questions where class_id = p_class and student_id = auth.uid()) >= 20 then
    raise exception 'question limit reached for this class';
  end if;
  select title into v_title from public.classes where id = p_class and status <> 'cancelled';
  if v_title is null then raise exception 'this class is not available'; end if;
  insert into public.class_questions (class_id, student_id, body)
  values (p_class, auth.uid(), trim(p_body)) returning id into v_id;
  if v_owner is not null then
    insert into public.notifications (user_id, title, body, href)
    values (v_owner, 'Question about a lesson', v_title, '/owner/classes/' || p_class || '/room');
  end if;
  return v_id;
end $$;

create or replace function public.answer_class_poll(p_poll uuid, p_choice int)
returns void language plpgsql security definer set search_path = public as $$
declare p public.class_polls%rowtype;
begin
  select * into p from public.class_polls where id = p_poll;
  if not found or auth.uid() is null or not public.student_in_class(p.class_id, auth.uid()) then
    raise exception 'not authorised';
  end if;
  if p.status <> 'open' then raise exception 'this quick check is closed'; end if;
  if p_choice < 0 or p_choice >= jsonb_array_length(p.options) then raise exception 'invalid choice'; end if;
  begin
    insert into public.class_poll_answers (poll_id, student_id, choice) values (p_poll, auth.uid(), p_choice);
  exception when unique_violation then
    raise exception 'you have already answered';
  end;
end $$;

-- Polls for a class as the caller may see them. While a check is open a learner gets
-- the question, options and their own choice only. The correct answer and the totals
-- appear once the tutor closes it. The Owner always sees everything.
-- Dropped first: migration 0009 changes the return type, and setup must stay re-runnable.
drop function if exists public.get_class_polls(uuid);
create function public.get_class_polls(p_class uuid)
returns table (id uuid, question text, options jsonb, status text, my_choice int, correct_index int, counts jsonb, answers int, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
declare v_owner boolean := public.is_owner();
begin
  if not (v_owner or public.student_in_class(p_class, auth.uid())) then raise exception 'not authorised'; end if;
  return query
    select p.id, p.question, p.options, p.status,
           (select a.choice from public.class_poll_answers a where a.poll_id = p.id and a.student_id = auth.uid()),
           case when v_owner or p.status = 'closed' then p.correct_index end,
           case when v_owner or p.status = 'closed' then
             (select coalesce(jsonb_agg(coalesce(t.n, 0) order by g.i), '[]'::jsonb)
                from generate_series(0, jsonb_array_length(p.options) - 1) as g(i)
                left join (select a.choice, count(*)::int as n from public.class_poll_answers a
                            where a.poll_id = p.id group by a.choice) t on t.choice = g.i)
           end,
           case when v_owner or p.status = 'closed' then
             (select count(*)::int from public.class_poll_answers a where a.poll_id = p.id)
           end,
           p.created_at
      from public.class_polls p where p.class_id = p_class order by p.created_at desc;
end $$;

create or replace function public.submit_class_feedback(p_class uuid, p_understanding int, p_comment text default null)
returns void language plpgsql security definer set search_path = public as $$
declare c public.classes%rowtype;
begin
  if auth.uid() is null or not public.student_in_class(p_class, auth.uid()) then raise exception 'not authorised'; end if;
  if p_understanding not between 1 and 4 then raise exception 'invalid rating'; end if;
  select * into c from public.classes where id = p_class;
  if c.status = 'cancelled' or c.starts_at > now() then raise exception 'feedback opens once the lesson has started'; end if;
  insert into public.class_feedback (class_id, student_id, understanding, comment)
  values (p_class, auth.uid(), p_understanding, nullif(left(trim(coalesce(p_comment, '')), 1000), ''))
  on conflict (class_id, student_id) do update
    set understanding = excluded.understanding, comment = excluded.comment, created_at = now();
end $$;

-- Tell the family when the tutor answers a question.
create or replace function public.on_question_answered() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.answer is not null and old.answer is distinct from new.answer then
    perform public.notify_family(new.student_id, 'Your question was answered',
      (select title from public.classes where id = new.class_id), '/classes/' || new.class_id);
  end if;
  return new;
end $$;
drop trigger if exists class_questions_answered on public.class_questions;
create trigger class_questions_answered after update on public.class_questions
  for each row execute function public.on_question_answered();

revoke execute on function public.student_in_class(uuid, uuid), public.set_class_rsvp(uuid, uuid, text, text),
  public.ask_class_question(uuid, text), public.answer_class_poll(uuid, int), public.get_class_polls(uuid),
  public.submit_class_feedback(uuid, int, text) from public, anon;
grant execute on function public.student_in_class(uuid, uuid), public.set_class_rsvp(uuid, uuid, text, text),
  public.ask_class_question(uuid, text), public.answer_class_poll(uuid, int), public.get_class_polls(uuid),
  public.submit_class_feedback(uuid, int, text) to authenticated, service_role;

-- ===================== 0009_board_behaviour_and_more.sql =====================
-- Class board (live whiteboard with answer boards), timed quick checks with points,
-- quiz topics for placement-test reports, behaviour notes, and account deletion.
-- Idempotent.

-- ===========================================================================
-- Class board
-- A board belongs to one class (class_id set) or is a saved lesson in the Owner's
-- library (class_id null) that can be copied into a class.
-- Drawing is stored as an append-only event log: every pen stroke, erase and clear
-- is a new row. Late joiners and replays rebuild the board by reading the log in
-- order, and live viewers receive the same rows through Supabase Realtime.
-- ===========================================================================
create table if not exists public.boards (
  id uuid primary key default gen_random_uuid(),
  class_id uuid unique references public.classes(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 160),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.board_pages (
  id uuid primary key default gen_random_uuid(),
  board_id uuid not null references public.boards(id) on delete cascade,
  position int not null default 0,
  background text not null default 'blank' check (background in ('blank','grid','lined','axes','numberline','image')),
  image_path text,               -- object in the private "boards" bucket when background = 'image'
  created_at timestamptz not null default now()
);
create index if not exists board_pages_board_idx on public.board_pages (board_id, position);

create table if not exists public.board_events (
  id bigint generated always as identity primary key,
  board_id uuid not null references public.boards(id) on delete cascade,
  page_id uuid not null references public.board_pages(id) on delete cascade,
  kind text not null check (kind in ('pen','highlighter','line','arrow','rect','circle','text','protractor','fraction','erase','clear')),
  data jsonb not null,           -- points / position / text / ids to erase; coordinates are 0..1 of the page
  created_at timestamptz not null default now(),
  check (octet_length(data::text) <= 200000)
);
create index if not exists board_events_page_idx on public.board_events (page_id, id);

-- What learners are looking at right now: the teacher's page, an open answer-board
-- prompt, and a learner's answer shown to the class.
create table if not exists public.board_state (
  board_id uuid primary key references public.boards(id) on delete cascade,
  page_id uuid references public.board_pages(id) on delete set null,
  prompt_id uuid,
  spotlight jsonb,               -- { "name": "Ada O.", "strokes": [...] } chosen by the Owner
  timer_ends_at timestamptz,     -- a countdown everyone sees
  updated_at timestamptz not null default now()
);

-- Answer boards: the Owner asks; each learner answers on their own mini board.
create table if not exists public.board_prompts (
  id uuid primary key default gen_random_uuid(),
  board_id uuid not null references public.boards(id) on delete cascade,
  question text not null check (char_length(question) between 1 and 500),
  status text not null default 'open' check (status in ('open','closed')),
  created_at timestamptz not null default now()
);

create table if not exists public.board_responses (
  id uuid primary key default gen_random_uuid(),
  prompt_id uuid not null references public.board_prompts(id) on delete cascade,
  board_id uuid not null references public.boards(id) on delete cascade,
  student_id uuid not null references public.profiles(id) on delete cascade,
  strokes jsonb not null default '[]'::jsonb,
  text_answer text check (char_length(text_answer) <= 500),
  submitted_at timestamptz not null default now(),
  unique (prompt_id, student_id),
  check (octet_length(strokes::text) <= 100000)
);

alter table public.boards enable row level security;
alter table public.board_pages enable row level security;
alter table public.board_events enable row level security;
alter table public.board_state enable row level security;
alter table public.board_prompts enable row level security;
alter table public.board_responses enable row level security;

-- Can the caller view this board? Owner always; otherwise a learner in the board's
-- class, or a verified parent of one. Library boards (no class) are Owner-only.
create or replace function public.can_view_board(p_board uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_owner() or exists (
    select 1 from public.boards b
    join public.class_students cs on cs.class_id = b.class_id
    where b.id = p_board and public.can_view_student(cs.student_id));
$$;

do $$ declare t text; begin
  foreach t in array array['boards','board_pages','board_events','board_state','board_prompts','board_responses'] loop
    execute format('drop policy if exists owner_all on public.%I', t);
    execute format('create policy owner_all on public.%I for all to authenticated
                    using (public.is_owner()) with check (public.is_owner())', t);
    execute format('drop policy if exists class_read on public.%I', t);
  end loop;
end $$;
create policy class_read on public.boards for select to authenticated using (public.can_view_board(id));
create policy class_read on public.board_pages for select to authenticated using (public.can_view_board(board_id));
create policy class_read on public.board_events for select to authenticated using (public.can_view_board(board_id));
create policy class_read on public.board_state for select to authenticated using (public.can_view_board(board_id));
create policy class_read on public.board_prompts for select to authenticated using (public.can_view_board(board_id));
-- A learner sees only their own answer board; the Owner sees all of them.
create policy class_read on public.board_responses for select to authenticated using (public.can_view_student(student_id));

create or replace function public.submit_board_response(p_prompt uuid, p_strokes jsonb, p_text text default null)
returns void language plpgsql security definer set search_path = public as $$
declare p public.board_prompts%rowtype; v_class uuid;
begin
  select * into p from public.board_prompts where id = p_prompt;
  if not found then raise exception 'not authorised'; end if;
  select class_id into v_class from public.boards where id = p.board_id;
  if auth.uid() is null or v_class is null or not public.student_in_class(v_class, auth.uid()) then
    raise exception 'not authorised';
  end if;
  if p.status <> 'open' then raise exception 'this question is closed'; end if;
  if jsonb_typeof(p_strokes) <> 'array' then raise exception 'invalid answer'; end if;
  insert into public.board_responses (prompt_id, board_id, student_id, strokes, text_answer, submitted_at)
  values (p_prompt, p.board_id, auth.uid(), p_strokes, nullif(left(trim(coalesce(p_text, '')), 500), ''), now())
  on conflict (prompt_id, student_id) do update
    set strokes = excluded.strokes, text_answer = excluded.text_answer, submitted_at = now();
end $$;

-- Private bucket for slide images.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('boards', 'boards', false, 5242880, array['image/png','image/jpeg','image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists ta_board_owner on storage.objects;
create policy ta_board_owner on storage.objects for all to authenticated
  using (bucket_id = 'boards' and public.is_owner()) with check (bucket_id = 'boards' and public.is_owner());
drop policy if exists ta_board_read on storage.objects;
create policy ta_board_read on storage.objects for select to authenticated
  using (bucket_id = 'boards'
         and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'
         and public.can_view_board(((storage.foldername(name))[1])::uuid));

-- ===========================================================================
-- Timed quick checks with points (a live quiz). A correct answer scores up to 1000
-- points, more for answering quickly; the class leaderboard shows first names only
-- and only when the Owner turned points on for that check.
-- ===========================================================================
alter table public.class_polls add column if not exists time_limit_seconds int check (time_limit_seconds between 5 and 600);
alter table public.class_polls add column if not exists points boolean not null default false;

create or replace function public.answer_class_poll(p_poll uuid, p_choice int)
returns void language plpgsql security definer set search_path = public as $$
declare p public.class_polls%rowtype;
begin
  select * into p from public.class_polls where id = p_poll;
  if not found or auth.uid() is null or not public.student_in_class(p.class_id, auth.uid()) then
    raise exception 'not authorised';
  end if;
  if p.status <> 'open' then raise exception 'this quick check is closed'; end if;
  -- Two seconds of grace for network delay.
  if p.time_limit_seconds is not null and now() > p.created_at + make_interval(secs => p.time_limit_seconds + 2) then
    raise exception 'time is up for this quick check';
  end if;
  if p_choice < 0 or p_choice >= jsonb_array_length(p.options) then raise exception 'invalid choice'; end if;
  begin
    insert into public.class_poll_answers (poll_id, student_id, choice) values (p_poll, auth.uid(), p_choice);
  exception when unique_violation then
    raise exception 'you have already answered';
  end;
end $$;

-- Same as before, plus the time limit and whether points are on (the return type
-- changes, so the function is dropped and recreated).
drop function if exists public.get_class_polls(uuid);
create function public.get_class_polls(p_class uuid)
returns table (id uuid, question text, options jsonb, status text, my_choice int, correct_index int, counts jsonb, answers int,
               created_at timestamptz, time_limit_seconds int, points boolean)
language plpgsql stable security definer set search_path = public as $$
declare v_owner boolean := public.is_owner();
begin
  if not (v_owner or public.student_in_class(p_class, auth.uid())) then raise exception 'not authorised'; end if;
  return query
    select p.id, p.question, p.options, p.status,
           (select a.choice from public.class_poll_answers a where a.poll_id = p.id and a.student_id = auth.uid()),
           case when v_owner or p.status = 'closed' then p.correct_index end,
           case when v_owner or p.status = 'closed' then
             (select coalesce(jsonb_agg(coalesce(t.n, 0) order by g.i), '[]'::jsonb)
                from generate_series(0, jsonb_array_length(p.options) - 1) as g(i)
                left join (select a.choice, count(*)::int as n from public.class_poll_answers a
                            where a.poll_id = p.id group by a.choice) t on t.choice = g.i)
           end,
           case when v_owner or p.status = 'closed' then
             (select count(*)::int from public.class_poll_answers a where a.poll_id = p.id)
           end,
           p.created_at, p.time_limit_seconds, p.points
      from public.class_polls p where p.class_id = p_class order by p.created_at desc;
end $$;
revoke execute on function public.get_class_polls(uuid) from public, anon;
grant execute on function public.get_class_polls(uuid) to authenticated, service_role;

create or replace function public.get_class_leaderboard(p_class uuid)
returns table (rank int, display_name text, points int, is_me boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_owner() or public.student_in_class(p_class, auth.uid())) then raise exception 'not authorised'; end if;
  return query
    with scored as (
      select a.student_id,
             sum(case when a.choice = p.correct_index then
                   case when p.time_limit_seconds is null then 1000
                        else greatest(500, round(1000 - 500 * least(1, extract(epoch from (a.created_at - p.created_at)) / p.time_limit_seconds)))::int end
                 else 0 end)::int as pts
        from public.class_poll_answers a
        join public.class_polls p on p.id = a.poll_id
       where p.class_id = p_class and p.points and p.status = 'closed' and p.correct_index is not null
       group by a.student_id)
    select (rank() over (order by s.pts desc))::int,
           split_part(pr.full_name, ' ', 1) || coalesce(' ' || left(nullif(split_part(pr.full_name, ' ', 2), ''), 1) || '.', ''),
           s.pts,
           s.student_id = auth.uid()
      from scored s join public.profiles pr on pr.id = s.student_id
     order by s.pts desc
     limit 10;
end $$;

-- ===========================================================================
-- Quiz topics: a placement or aptitude test reports results topic by topic.
-- ===========================================================================
alter table public.quiz_questions add column if not exists topic text check (char_length(topic) <= 80);

create or replace function public.get_topic_breakdown(p_submission uuid)
returns table (topic text, correct int, total int)
language plpgsql stable security definer set search_path = public as $$
declare s public.submissions%rowtype;
begin
  select * into s from public.submissions where id = p_submission;
  if not found or not public.can_view_student(s.student_id) then raise exception 'not authorised'; end if;
  return query
    select coalesce(nullif(q.topic, ''), 'General'),
           count(*) filter (where (s.answers ->> q.id::text) ~ '^[0-9]{1,2}$' and (s.answers ->> q.id::text)::int = q.correct_index)::int,
           count(*)::int
      from public.quiz_questions q
     where q.assignment_id = s.assignment_id
     group by 1 order by 1;
end $$;

-- ===========================================================================
-- Behaviour: merits and concerns the Owner records; the learner and parents see them.
-- ===========================================================================
create table if not exists public.behaviour_notes (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete cascade,
  class_id uuid references public.classes(id) on delete set null,
  kind text not null check (kind in ('merit','concern')),
  category text not null check (char_length(category) between 2 and 60),
  note text check (char_length(note) <= 1000),
  points int not null default 1 check (points between 1 and 10),
  created_at timestamptz not null default now()
);
create index if not exists behaviour_student_idx on public.behaviour_notes (student_id, created_at desc);
alter table public.behaviour_notes enable row level security;
drop policy if exists owner_all on public.behaviour_notes;
create policy owner_all on public.behaviour_notes for all to authenticated using (public.is_owner()) with check (public.is_owner());
drop policy if exists family_read on public.behaviour_notes;
create policy family_read on public.behaviour_notes for select to authenticated using (public.can_view_student(student_id));

create or replace function public.on_behaviour_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.notify_family(new.student_id,
    case when new.kind = 'merit' then 'Merit awarded' else 'Behaviour note' end, new.category, '/reports');
  return new;
end $$;
drop trigger if exists behaviour_notify on public.behaviour_notes;
create trigger behaviour_notify after insert on public.behaviour_notes
  for each row execute function public.on_behaviour_insert();

-- ===========================================================================
-- Account deletion. Called by the server (service role) after it has verified the
-- person's password and their typed confirmation. Personal and learning data are
-- removed. Invoices and payments are kept, as the law requires for financial
-- records, but are no longer linked to a name, email or phone number.
-- ===========================================================================
create or replace function public.erase_account(p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
declare v_role text;
begin
  if auth.role() <> 'service_role' then raise exception 'not authorised'; end if;
  select role into v_role from public.profiles where id = p_user;
  if v_role is null then raise exception 'account not found'; end if;
  if v_role = 'owner' then raise exception 'the owner account cannot be deleted this way'; end if;

  delete from public.message_threads where participant_id = p_user;            -- and their messages
  delete from public.notifications where user_id = p_user;
  delete from public.push_subscriptions where user_id = p_user;
  delete from public.parent_student_links where parent_id = p_user or student_id = p_user;
  delete from public.class_rsvps where student_id = p_user;
  update public.class_rsvps set responded_by = null where responded_by = p_user;
  delete from public.class_questions where student_id = p_user;
  delete from public.class_poll_answers where student_id = p_user;
  delete from public.class_feedback where student_id = p_user;
  delete from public.board_responses where student_id = p_user;
  delete from public.behaviour_notes where student_id = p_user;
  delete from public.submissions where student_id = p_user;
  delete from public.assignment_students where student_id = p_user;
  delete from public.attendance where student_id = p_user;
  delete from public.class_students where student_id = p_user;
  delete from public.material_students where student_id = p_user;
  delete from public.reports where student_id = p_user;
  delete from public.certificates where student_id = p_user;
  delete from public.student_enrolments where student_id = p_user;
  delete from public.student_notes where student_id = p_user;
  delete from public.guardian_links where student_id = p_user;
  delete from public.quiz_starts where student_id = p_user;
  delete from public.applications where student_id = p_user
     or lower(guardian_email) = (select lower(email) from public.profiles where id = p_user and role = 'parent');

  update public.profiles set
    full_name = 'Deleted account', email = 'deleted+' || p_user || '@invalid.invalid', phone = null,
    date_of_birth = null, school_year = null, curriculum = null, location = null, learning_needs = null,
    goals = null, status = 'inactive'
  where id = p_user;

  insert into public.audit_log (actor_id, action, entity, entity_id, meta)
  values (null, 'account.erased', 'profile', p_user::text, jsonb_build_object('role', v_role));
end $$;

revoke execute on function public.can_view_board(uuid), public.submit_board_response(uuid, jsonb, text),
  public.get_class_leaderboard(uuid), public.get_topic_breakdown(uuid), public.erase_account(uuid) from public, anon;
grant execute on function public.can_view_board(uuid), public.submit_board_response(uuid, jsonb, text),
  public.get_class_leaderboard(uuid), public.get_topic_breakdown(uuid) to authenticated, service_role;
revoke execute on function public.erase_account(uuid) from authenticated;
grant execute on function public.erase_account(uuid) to service_role;

-- ===========================================================================
-- Live updates: publish board and quick-check changes through Supabase Realtime.
-- Realtime applies the same RLS policies to each subscriber.
-- ===========================================================================
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['board_events','board_pages','board_state','board_prompts','board_responses','class_polls'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;
